import {CENTER,DEMO_POINTS,escapeHtml as e,canRoute,haversine,planOrder,routeParts,mapsURL,validCoordinate} from './core.mjs';
import {discover,weather,sights,getCache,CACHE_PREFIX} from './api.mjs';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const state={demo:true,ids:[],filter:'all',query:'',trust:'all',osm:[],sights:[],location:null,ordering:'manual',start:'center'};
try{const saved=JSON.parse(localStorage.getItem('alunue-refill-state-v1')||'null');if(saved){state.demo=typeof saved.demo==='boolean'?saved.demo:true;state.ids=Array.isArray(saved.ids)?saved.ids.filter(x=>typeof x==='string'):[];state.ordering=['manual','direct','discover'].includes(saved.ordering)?saved.ordering:'manual';}}catch{}
const cachedOSM=getCache('osm-evora'),cachedSights=getCache('sights-evora');state.osm=Array.isArray(cachedOSM?.data)?cachedOSM.data:[];state.sights=Array.isArray(cachedSights?.data)?cachedSights.data:[];
function all(){return [...(state.demo?DEMO_POINTS:[]),...state.osm,...state.sights];}
function save(){try{localStorage.setItem('alunue-refill-state-v1',JSON.stringify({demo:state.demo,ids:state.ids,ordering:state.ordering}));}catch{toast('Armazenamento indisponível. A sessão continua disponível; guarda o itinerário em texto.');}}
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',6500);}
function origin(){if(state.start==='gps'){if(!state.location)throw Error('Usa a localização ou escolhe um início manual.');return state.location;}if(state.start==='manual'){const p={lat:Number($('#lat').value),lon:Number($('#lon').value)};if($('#lat').value===''||$('#lon').value===''||!validCoordinate(p))throw Error('Introduz latitude e longitude válidas.');return p;}return state.start==='campus'?{lat:38.5684,lon:-7.9105}:CENTER;}
function selected(){return state.ids.map(id=>all().find(p=>p.id===id)).filter(Boolean);}
function readyStops(){return selected().filter(p=>canRoute(p,state.demo));}
function renderCards(){let points=all().filter(p=>(state.filter==='all'||p.kind===state.filter)&&p.name.toLowerCase().includes(state.query.toLowerCase())&&(state.trust!=='routeable'||canRoute(p,state.demo)));if(state.location)points.sort((a,b)=>haversine(state.location,a)-haversine(state.location,b));$('#inventory-note').textContent=`${state.osm.filter(p=>p.kind==='water').length} candidatos de água no mapa · 0 pontos reais verificados de forma independente. Os dados guardados mantêm o estado não verificado.`;$('#cards').innerHTML=points.length?points.map(p=>{const added=state.ids.includes(p.id),allowed=canRoute(p,state.demo);return `<article class="place"><div class="card-top"><span class="place-type">${e(({water:'Água',partner:'Loja independente',grocery:'Supermercado',sight:'Local de interesse'}[p.kind]||p.kind))}</span><span class="badge ${p.demo||p.status==='candidate'?'warn':''}">${p.demo?'DEMONSTRAÇÃO':p.status==='candidate'?'POR VERIFICAR':'REFERÊNCIA CULTURAL'}</span></div><h3>${e(p.name)}</h3><p>${e(p.opening||'Horário desconhecido')}</p><p>${p.demo?'Cenário fictício para explorar o protótipo.':p.kind==='water'?'O mapa não confirma potabilidade, acesso gratuito ou disponibilidade atual.':p.kind==='grocery'?'Sem garantia de preços ou horários atuais. Pesquisa pelo nome da loja.':'Paragem cultural opcional. É necessário confirmar acesso e horários.'}</p>${state.location?`<p class="fine">${haversine(state.location,p).toFixed(2)} km em linha reta; a distância a pé é diferente.</p>`:''}<details><summary>Fonte e verificação</summary><p>${e(p.sourceLabel)}<br>${e(p.access||'Acesso desconhecido')}<br>${p.checkedAt?`Verificado em ${e(p.checkedAt)}`:'Sem data de verificação independente'}</p>${p.source?`<a target="_blank" rel="noopener" href="${e(p.source)}">Consultar fonte ↗</a>`:''}</details><button data-add="${e(p.id)}" ${!allowed?'disabled':''}>${added?'Retirar do percurso':!allowed?'Verificação necessária antes de criar percurso':'Adicionar ao percurso +'}</button></article>`;}).join(''):'<div class="empty"><h3>Não há locais correspondentes.</h3><p>Experimenta outro filtro, ativa a demonstração ou consulta candidatos no mapa. Não há inventário verificado disponível.</p></div>';$$('[data-add]').forEach(b=>b.onclick=()=>{const id=b.dataset.add;state.ids=state.ids.includes(id)?state.ids.filter(x=>x!==id):[...state.ids,id];save();render();});}
function ordered(){return planOrder(origin(),readyStops(),state.ordering);}
function itinerary(){const stops=ordered();if(!stops.length)return 'Nenhuma paragem selecionada.';return ['Itinerário AlunUÉ',stops.some(p=>p.demo)?'DEMONSTRAÇÃO: pontos fictícios; não dependas deles para obter água.':'Confirma acesso e horários antes de sair.',`Início: ${origin().lat}, ${origin().lon}`,...stops.map((p,i)=>`${i+1}. ${p.name} (${p.lat}, ${p.lon})${p.demo?' [DEMO]':''}`),...routeParts(origin(),stops).map((p,i)=>`Google Maps, parte ${i+1}: ${p.url}`),'A ordem é uma estimativa, não um percurso de ruas otimizado.'].join('\n');}
function renderJourney(){const list=selected();$('#count').textContent=String(list.length);$('#stops').innerHTML=list.length?list.map((p,i)=>`<li><b>${e(p.name)}</b> <span class="badge">${p.demo?'DEMO':e(({candidate:'por verificar',reference:'referência',demo:'exemplo',checked:'verificado'})[p.status]||p.status)}</span><br><button data-up="${i}" ${i===0?'disabled':''} aria-label="Mover ${e(p.name)} para antes">↑ Antes</button><button data-down="${i}" ${i===list.length-1?'disabled':''} aria-label="Mover ${e(p.name)} para depois">↓ Depois</button><button data-remove="${e(p.id)}">Retirar</button></li>`).join(''):'<p>Sem paragens. Adiciona um exemplo, supermercado ou referência cultural em Descobrir.</p>';$$('[data-remove]').forEach(b=>b.onclick=()=>{state.ids=state.ids.filter(id=>id!==b.dataset.remove);save();render();});for(const [attr,delta] of [['up',-1],['down',1]])$$(`[data-${attr}]`).forEach(b=>b.onclick=()=>{state.ordering='manual';$('#ordering').value='manual';const idx=Number(b.dataset[attr]);const ids=list.map(p=>p.id);[ids[idx],ids[idx+delta]]=[ids[idx+delta],ids[idx]];state.ids=ids;save();render();});try{const stops=ordered();$('#route-summary').textContent=stops.length?`${stops.length} paragem(ns) elegível(eis). ${stops.some(p=>p.demo)?'Inclui locais fictícios de demonstração. ':''}${state.ordering==='manual'?'A exportação conserva a tua ordem.':'Ordem sugerida para exportação: '+stops.map(p=>p.name).join(' → ')} O Google Maps calcula o percurso nas ruas.`:'';$('#exports').innerHTML=stops.length?routeParts(origin(),stops).map((p,i)=>`<a class="button primary" target="_blank" rel="noopener" href="${e(p.url)}">Abrir indicações pedonais${stops.length>4?` · parte ${i+1}`:''} ↗</a>`).join('')+`<details><summary>Etapas pedonais individuais · alternativa</summary>${stops.map((p,i)=>`<a target="_blank" rel="noopener" href="${e(mapsURL(i===0?origin():stops[i-1],[p]))}">Etapa ${i+1}: ${e(p.name)} ↗</a>`).join('')}</details>`:'';}catch(error){$('#route-summary').textContent=error.message;$('#exports').innerHTML='';}}
function render(){renderCards();renderJourney();$('#demo-toggle').textContent=state.demo?'Demonstração ativa':'Demonstração desativada';$('#demo-toggle').setAttribute('aria-pressed',String(state.demo));$('#mode-notice').innerHTML=state.demo?'<b>Explora uma demonstração.</b> Os pontos de água e lojas são cenários fictícios. Os candidatos do mapa precisam de verificação.':'<b>Descoberta no mapa.</b> Este protótipo não tem pontos de água gratuitos verificados. Os candidatos continuam por verificar; supermercados e locais culturais são opcionais.';}
function navigate(){const key=location.hash.slice(1)||'discover',valid=['discover','journey','community','project'].includes(key)?key:'discover';$$('.view').forEach(v=>v.hidden=v.id!==valid);$$('[data-tab]').forEach(a=>{if(a.dataset.tab===valid)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});document.title=`${valid==='discover'?'Descobrir':valid==='journey'?'O meu percurso':valid==='community'?'Comunidade':'O projeto'} · AlunUÉ Refill`;}
addEventListener('hashchange',navigate);
$('#search').oninput=x=>{state.query=x.target.value;renderCards();};$('#trust').onchange=x=>{state.trust=x.target.value;renderCards();};$$('[data-filter]').forEach(b=>b.onclick=()=>{state.filter=b.dataset.filter;$$('[data-filter]').forEach(x=>x.classList.toggle('selected',x===b));renderCards();});
$('#demo-toggle').onclick=()=>{state.demo=!state.demo;state.ids=state.ids.filter(id=>!id.startsWith('demo-'));save();render();};
$('#locate').onclick=()=>{if(!navigator.geolocation){toast('Localização não suportada. Escolhe um início em O meu percurso.');return;}$('#locate').disabled=true;navigator.geolocation.getCurrentPosition(pos=>{state.location={lat:pos.coords.latitude,lon:pos.coords.longitude};$('#locate').disabled=false;toast('Localização definida nesta sessão. As distâncias são estimativas em linha reta.');render();},()=>{$('#locate').disabled=false;toast('Localização indisponível. Escolhe o centro, CLV ou coordenadas manuais.');},{enableHighAccuracy:false,timeout:10000,maximumAge:60000});};
$('#start').onchange=x=>{state.start=x.target.value;$('#manual').hidden=state.start!=='manual';renderJourney();};$('#ordering').value=state.ordering;$('#ordering').onchange=x=>{state.ordering=x.target.value;save();renderJourney();};for(const sel of ['#lat','#lon'])$(sel).oninput=renderJourney;$('#clear').onclick=()=>{state.ids=[];save();render();};
async function load(button,fn,apply){button.disabled=true;$('#api-status').textContent='A ligar… aguarda.';try{const result=await fn();apply(result.data);$('#api-status').textContent=`${result.stale?'Serviço indisponível · dados antigos guardados':result.cached?'A usar dados guardados':'Dados atualizados'} · ${new Date(result.at).toLocaleString('pt-PT',{timeZone:'Europe/Lisbon'})} Lisboa. ${result.error||''}`;render();}catch(error){$('#api-status').textContent=`Não foi possível carregar: ${error.message} A lista e o itinerário continuam disponíveis.`;}finally{button.disabled=false;}}
$('#load-osm').onclick=()=>load($('#load-osm'),()=>discover(false),data=>{state.osm=data;});$('#load-sights').onclick=()=>load($('#load-sights'),sights,data=>{state.sights=data;});$('#load-weather').onclick=()=>load($('#load-weather'),weather,data=>{$('#weather').textContent=`${data.temperature_2m}°C · sensação térmica de ${data.apparent_temperature??'desconhecida'}°C`;});
$('#copy').onclick=async()=>{try{const text=itinerary();if(!navigator.clipboard)throw Error('Área de transferência indisponível');await navigator.clipboard.writeText(text);toast('Itinerário copiado.');}catch(error){toast('Cópia indisponível. Usa Guardar em texto.');}};$('#share').onclick=async()=>{try{const text=itinerary();if(!navigator.share){toast('Partilha indisponível. Copia ou guarda o itinerário.');return;}await navigator.share({title:'Percurso AlunUÉ',text});}catch(error){if(error.name!=='AbortError')toast('A partilha falhou. Copia ou guarda o itinerário.');}};$('#download').onclick=()=>{try{const blob=new Blob([itinerary()],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='alunue-refill-itinerary.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(error){toast(error.message);}};
$('#suggest').onsubmit=event=>{event.preventDefault();const form=event.target,values=new FormData(form);try{const old=JSON.parse(localStorage.getItem('alunue-refill-suggestions-v1')||'[]');old.push({place:values.get('place'),note:values.get('note'),at:new Date().toISOString(),status:'local-draft'});localStorage.setItem('alunue-refill-suggestions-v1',JSON.stringify(old));$('#suggest-status').textContent='Guardado apenas neste navegador. Nada foi enviado ou verificado.';form.reset();}catch{$('#suggest-status').textContent='Armazenamento indisponível. O rascunho fica no formulário; copia-o antes de sair.';}};
$('#delete-local').onclick=()=>{try{Object.keys(localStorage).filter(k=>k.startsWith('alunue-refill-')||k.startsWith(CACHE_PREFIX)).forEach(k=>localStorage.removeItem(k));}catch{}state.ids=[];state.osm=[];state.sights=[];state.location=null;$('#weather').textContent='';$('#suggest').reset();$('#suggest-status').textContent='Preferências, dados e sugestões guardados apagados.';render();toast('Dados locais apagados. O navegador gere os ficheiros da interface offline.');};
let installPrompt;addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;$('#install').hidden=false;});$('#install').onclick=async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null;$('#install').hidden=true;}};
function networkState(){if(!navigator.onLine)toast('Sem internet: usa os dados e o itinerário guardados. Mapas externos e serviços atuais exigem ligação.');}addEventListener('offline',networkState);addEventListener('online',()=>toast('Ligação restabelecida. As consultas externas só são feitas quando as pedes.'));
if('serviceWorker' in navigator&&location.protocol==='https:')navigator.serviceWorker.register('./sw.js').then(()=>{$('#offline-state').textContent='Interface offline registada. Conclui uma visita com internet e volta a abrir para verificar o suporte no telemóvel. Os dados só são guardados após uma consulta bem-sucedida. Mapas externos exigem ligação.';}).catch(()=>{$('#offline-state').textContent='A interface offline não está disponível neste navegador ou alojamento. Guarda o itinerário em texto.';});
render();navigate();networkState();
